const KEY = ['AKDENİZ!', 'AKDENİZ\'DİR.', 'AKDENİZ', 'KOCATEPE.', 'KOCATEPE\'DE', 'BÜYÜK', 'TAARRUZ', 'TINAZTEPE\'Yİ', 'MEHMETÇİK', 'DUMLUPINAR\'DA,', 'BAŞKOMUTANLIK', 'BAŞKOMUTAN', '"ORDULAR!', 'İLERİ!"', 'SÜVARİLER', 'TRİKUPİS', 'İZMİR\'E', 'İZMİR\'İN', 'ZAFER', 'BAYRAĞI', 'ÇEMBER'];
const DURATION = 62.971 + 2.2;
const OUTRO_AT = DURATION - 1.6;
function camera(ctx, lt, d, z0 = 1, z1 = 1.06, cx = W / 2, cy = 760) {
  const z = lerp(z0, z1, eInOut(lt / d)); ctx.translate(cx, cy); ctx.scale(z, z); ctx.translate(-cx, -cy);
}
const TRK = '#b7342a', ENM = '#4f6378';
// ---- haritalar ----
const TR = { x: 520, y: 840, lon: 35.4, lat: 39, k: 46 };
const PT = (lon, lat) => proj(TR, lon, lat);
function geoMap(ctx, m, geo, o = {}) {
  drawSea(ctx, [-400, -400, W + 800, H + 800]);
  geo.forEach(c => c.r.forEach(r => shape(ctx, r.map(p => proj(m, p[0], p[1])), c.a === 'TUR' ? (o.fill || '#efdcae') : '#d9c393', c.a === 'TUR' ? C.ink : 'rgba(42,29,21,.55)', c.a === 'TUR' ? 4.5 : 2.5, .6)));
}
