const SK = { x: 520, y: 820, lon: 31.75, lat: 39.75, k: 300 };
const PS = (lon, lat) => proj(SK, lon, lat);
const SAKARYA_R = [[30.9, 39.25], [31.3, 39.3], [31.65, 39.35], [32.0, 39.42], [32.2, 39.52], [32.25, 39.7], [32.1, 39.9], [31.9, 40.02], [31.55, 40.07], [31.2, 40.15], [30.9, 40.3], [30.6, 40.45]];
